        private void TryLoadSeoByInformationSlug()
        {
            string slug = GetInformationSlugFromRequest();
            if (string.IsNullOrEmpty(slug))
            {
                return;
            }

            INFO_Information objInformation = new INFO_Information();
            DataTable dtbData = objInformation.GetDataTable(
                "INFO_Information_SIMS_Detail",
                "@InformationLink", slug,
                "@LanguageID", ResManager.CurrentLanguageID
            );

            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                return;
            }

            DataRow drw = dtbData.Rows[0];
            bolIsArticlePage = true;

            if (string.IsNullOrEmpty(strTitle))
            {
                strTitle = drw["Title"].ToString();
            }

            if (string.IsNullOrEmpty(strDescription))
            {
                if (drw["Description"].ToString() == "")
                {
                    strDescription = HttpUtility.HtmlDecode(System.Text.RegularExpressions.Regex.Replace(drw["Brief"].ToString(), "<(.|\n)*?>", ""));
                }
                else
                {
                    strDescription = drw["Description"].ToString();
                }
            }

            if (string.IsNullOrEmpty(strKeyWork))
            {
                strKeyWork = drw["Keyword"].ToString();
            }

            if (string.IsNullOrEmpty(strImages))
            {
                strImages = BuildThumbImageUrl(drw);
            }
        }

        private string GetInformationSlugFromRequest()
        {
            if (Session != null && Session["RouterResolvedSlug"] != null)
            {
                string sessionSlug = Convert.ToString(Session["RouterResolvedSlug"]).Trim();
                if (!string.IsNullOrEmpty(sessionSlug))
                {
                    return sessionSlug.Trim('/');
                }
            }

            if (Context != null && Context.Items["slug"] != null)
            {
                string contextSlug = Convert.ToString(Context.Items["slug"]).Trim();
                if (!string.IsNullOrEmpty(contextSlug))
                {
                    return contextSlug.Trim('/');
                }
            }

            string routeSlug = string.Empty;
            if (Page != null && Page.RouteData != null && Page.RouteData.Values["slug"] != null)
            {
                routeSlug = Convert.ToString(Page.RouteData.Values["slug"]).Trim().Trim('/');
            }

            if (string.IsNullOrEmpty(routeSlug))
            {
                routeSlug = (Request["slug"] ?? string.Empty).Trim().Trim('/');
            }

            if (string.IsNullOrEmpty(routeSlug))
            {
                string[] keys = { "ilink", "InformationLink" };
                foreach (string key in keys)
                {
                    string value = (Request[key] ?? string.Empty).Trim();
                    if (!string.IsNullOrEmpty(value))
                    {
                        return value.Trim('/');
                    }
                }

                return string.Empty;
            }

            if (routeSlug.IndexOf("/", StringComparison.Ordinal) >= 0)
            {
                string[] segments = routeSlug.Split(new[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
                if (segments.Length > 0)
                {
                    return segments[segments.Length - 1];
                }
            }

            return routeSlug;
        }

        private string BuildThumbImageUrl(DataRow row)
        {
            if (row == null || row.Table == null || !row.Table.Columns.Contains("ThumbImage") || row["ThumbImage"] == DBNull.Value)
            {
                return string.Empty;
            }

            string image = Convert.ToString(row["ThumbImage"]).Trim();
            if (string.IsNullOrEmpty(image))
            {
                return string.Empty;
            }

            if (image.StartsWith("/") || image.StartsWith("http", StringComparison.OrdinalIgnoreCase))
            {
                return GetAbsoluteUrl(image);
            }

            int informationID = 0;
            if (row.Table.Columns.Contains("InformationID") && row["InformationID"] != DBNull.Value)
            {
                informationID = Convert.ToInt32(row["InformationID"]);
            }

            string paddedID = "000000" + informationID;
            string subFolder = "Information" + paddedID.Substring(paddedID.Length - 6);
            return GetAbsoluteUrl(WebGlobal.InformationThumbDirectory + "/" + subFolder + "/" + image);
        }

        private string GetAbsoluteUrl(string url)
        {
            if (string.IsNullOrEmpty(url))
            {
                return string.Empty;
            }

            if (url.StartsWith("http://", StringComparison.OrdinalIgnoreCase) ||
                url.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
            {
                return url;
            }

            if (Request == null || Request.Url == null)
            {
                return url;
            }

            string host = Request.Url.Scheme + "://" + Request.Url.Authority;
            if (!url.StartsWith("/"))
            {
                url = "/" + url;
            }

            return host + url;
        }

    }
}

